def retry_delays(attempts, base=0.5, cap=8.0):
    if attempts < 1 or base < 0 or cap < 0:
        raise ValueError("invalid retry policy")
    return [min(cap, base * 2 ** (retry + 1)) for retry in range(attempts)]

