import unittest
from solution import retry_delays

class VisibleTests(unittest.TestCase):
    def test_no_retries(self):
        self.assertEqual(retry_delays(1), [])

    def test_exponential_sequence(self):
        self.assertEqual(retry_delays(5), [0.5, 1.0, 2.0, 4.0])

    def test_caps_each_delay(self):
        self.assertEqual(retry_delays(6, base=2, cap=5), [2, 4, 5, 5, 5])

