import unittest
from solution import retry_delays

class HiddenTests(unittest.TestCase):
    def test_cap_below_base(self):
        self.assertEqual(retry_delays(4, base=9, cap=3), [3, 3, 3])

    def test_zero_delays(self):
        self.assertEqual(retry_delays(4, base=0), [0, 0, 0])
        self.assertEqual(retry_delays(3, cap=0), [0, 0])

    def test_fractional_base(self):
        self.assertEqual(retry_delays(4, base=0.125, cap=0.3), [0.125, 0.25, 0.3])

    def test_invalid_policy(self):
        for kwargs in ({"attempts": 0}, {"attempts": -1}, {"attempts": 2, "base": -1}, {"attempts": 2, "cap": -1}):
            with self.subTest(kwargs=kwargs), self.assertRaises(ValueError):
                retry_delays(**kwargs)
